"""版114b を外す（測る道具を版114 の前の形に）"""

FILES = {'measure_cl112.py': ('a5ff8cde3632e2c5cd489873badd11ef9723c9df7f7ff5d5cc993cbab716f200', '"""版111 の上で、CL の体数と CL → 皮質 の線の引き方だけを変えて測る（arkhe の ~/anaplex で。保存しない・網のファイルは変えない。版112 を作る前の確かめ）\n  python3 measure_cl112.py CLの体数 [歩=15000] [刻み=200]      （CLの体数 5 ＝ 今の網そのまま）\n  python3 measure_cl112.py CLの体数 [歩] [刻み] --ppn      （PPN の自分で撃つ分 i0 を体ごとにばらす。下の「--ppn」）\n  python3 measure_cl112.py CLの体数 --count                    （網を組んで辺・線の数を出して終わる。VRAM の見込み用）\n  何のため：analyze111c（data/arkhe_analyze111c_1117.txt）：皮質が同じ歩にそろって撃つのは、CL が 5体で、皮質の表現の体がどれも同じ 5体から\n    40本（重なりあり ＝ 1体から約8本）受けるから。10 §7【み】10-23「（CL 5 ほか）ちゃんと動かなかったら増やす」\n  変えるもの（組む前に torch_brain の N_CL を差し替え、組んだあと cl_src を引き直す。ほかは版111 のまま）\n    ・CL の体数 N_CL（5 → 指定の数）\n    ・CL → 皮質 の線：受け手1体の 40本を、別々の CL の体から引く（重なりなし。体数が 40 より少ないときは今の引き方のまま）\n    K_CL 40・重さ・閾値・PPN → CL 8本・CL の目標 11Hz は変えない（K_CL のコードの注は「CL だけ・抑制 0 で 3.3Hz【計算】」）\n  --ppn（11-17）：analyze ⑥（data/arkhe_analyze6_1117.txt）で PPN 512体が同じ歩にそろって撃っていた（体の 50% 以上が撃つ歩に発火の 68〜71%）。\n    【コード】核の i0 は核の中の全部の体で同じ値（torch.full）。【ヒト】PPN の細胞ごとの率は 23.2 ± 15.6Hz（32体、JNNP 2010。台帳_核の値）\n    ⇒ 体ごとの率を、平均 23.2・SD 15.6 の対数正規【C】から引き、i0 に「その率で自分で撃つ行き着く先 ÷ 23.2Hz の行き着く先」を掛ける\n      （行き着く先 ＝ 1 ÷ (1 − e^(−間隔/40ms))、torch_brain の NUC_VINF["PPN"] と同じ式。ノブの倍率はそのまま掛かる）\n    ⚠️ 抑制（内節・網様部）の下での実際の率は式どおりにならない ⇒ PPN の率の列で見る。変えるのは PPN だけ\n  --ppn-free（11-17）：--ppn では PPN のそろいが取れなかった（data/arkhe_cl112_256_ppn_1117.txt：PPN の一度に撃つ分 60〜76% のまま）。\n    【コード】PPN へ入るのは 内節 → PPN・網様部 → PPN の抑制 各64本だけ（torch_brain 802行）⇒ PPN の体はどれもほぼ同じ抑制の波を受ける\n    ⇒ 測るためだけに PPN を入力から切り離す：内節・網様部 → PPN の線の重さを 0・--ppn のばらしを掛ける（i0 のノブの倍率 2.81 はそのまま。--ppn-k=値 で変えられる）\n       ＝ PPN の体がそれぞれ人の率（23.2 ± 15.6Hz）でばらばらに自分で撃つだけの形\n    見ること：PPN がばらばらに撃てば、CL と皮質の「一度に撃つ」は消えるか（消えれば元は 基底核 → PPN の波・消えなければ別にもある）\n    ⚠️ 人から外れた形（内節・網様部 → PPN は人・霊長類にある線）。測るためだけで、版にはしない\n  --ppn-noi（11-17、--ppn-free と一緒に使う）：--ppn-free でも PPN の一度に撃つ分は 89〜96%（data/arkhe_cl112_256_ppnfree_1117.txt）⇒ PPN の中でそろう。\n    【コード 版111、容器で数えた】PPN の領野は 体 512・中の抑制の体 98。辺は 体 → 抑制の体 の興奮 17,640本（98 × 180【C】30 §4）と\n    抑制の体 → 体 の抑制 36,100本。体どうしの興奮は無い（10 §10・20_今の網「中の興奮の横なし」のとおり）。\n    ⇒ 512体がみな同じ 98体の抑制を受ける輪（体が撃つ → 抑制の体 → 全体を抑える）がそろえている疑い\n    ⇒ 測るためだけに、PPN の中の 抑制の体 → 体 の辺の重さを 0（刈り込みで 1000歩ごとに少し生え直る）\n    ⚠️ 人から外れた形。版にはしない\n  --table（11-17）：毎歩、領野・核ごとの「撃った体の割合」を表にして cl112_table.npz に書く（measure_wave111c と同じ形 ⇒ analyze_wave111c で読める）\n    毎歩の仕事が1つ増える（体の数の累積和 1回・領野の端の読み）\n  出すもの：刻みごとに wave111b の列 ＋ そろい（その刻みで皮質が黙った歩の割合・皮質の発火のうち「皮質の 20% 以上が同じ歩に撃った歩」に入る割合）\n    ＋ CL の率 ＋ 声・自発・言えた\n  毎歩に足す仕事：表現の発火（体の数）を1本の数えへ足す 1回・皮質の発火の平均 1回（数 1つを読む）。線・辺には触らない・少ない箱への足し込みなし\n  刻みごと（200歩に1回）：下からの線の道ごとの切り出しの和・CL の和（wave111b と同じ）\n"""\nimport sys, numpy as np, torch\nimport babble as B, brainstem as BS, torch_area as T\nimport torch_brain as TB, life as L\nfrom torch_brain import Brain, NAMES\n\nargs = [a for a in sys.argv[1:] if not a.startswith("--")]\nif not args:\n    sys.exit("CL の体数を1つ（5 ＝ 今のまま）")\nNCL = int(args[0])\nNS = int(args[1]) if len(args) > 1 else 15000\nEV = int(args[2]) if len(args) > 2 else 200\nCOUNT = "--count" in sys.argv\nPPN_FREE = "--ppn-free" in sys.argv\nPPN_NOI = "--ppn-noi" in sys.argv\nTABLE = "--table" in sys.argv\nPPN_SPREAD = "--ppn" in sys.argv or PPN_FREE\nNP_TEST = 200\nfor a_ in sys.argv[1:]:\n    if a_.startswith("--np="):\n        NP_TEST = int(a_[5:])\nTEST = "--test" in sys.argv\nif TEST:\n    B.DEV = "cpu"\ndev = B.DEV\nif B.VERSION not in (111, 112, 113):            # 11-19：版112 は CL 256・別々の体からが網に入った ⇒ 差し替えなしで同じ列を出す\n    raise SystemExit(f"⚠️ 版 {B.VERSION}：この道具は版111・112 の上で回す")\nif B.VERSION == 112:\n    assert TB.N_CL == NCL, f"版112 の CL は {TB.N_CL} 体（差し替えはしない）⇒ {TB.N_CL} を渡す"\nelse:\n    assert TB.N_CL == 5 and TB.N_NEW["CL"] == 5, "N_CL が思っていた値でない"\nTB.N_CL = NCL\nTB.N_NEW["CL"] = NCL\ntorch.manual_seed(0)\nb = Brain(T.Prior.load("prior_v1.npz", dev=dev), n_partner=(NP_TEST if TEST else 9100), hippo_scale=20.0, n_ear=B.N_EAR, dev=dev)\nb.bs.set_state(BS.WAKE)\nlife = B.life_of(b, True, np.random.default_rng(0), np.random.default_rng(1))\ng = b.g\nassert b.n["CL"] == NCL and len(b.cl_spk) == NCL, "CL の体数が入っていない"\nnr_ = len(b.cl_ch)\nK = len(b.cl_w) // nr_\nDISTINCT = NCL >= K\nif DISTINCT and B.VERSION == 111:                                             # 受け手ごとに別々の CL の体から K 本（重なりなし）\n    gc_ = torch.Generator(device="cpu"); gc_.manual_seed(112)\n    src = torch.empty(nr_, K, dtype=torch.long)\n    for a0 in range(0, nr_, 512):\n        src[a0:a0 + 512] = torch.rand(min(512, nr_ - a0), NCL, generator=gc_).argsort(1)[:, :K]\n    assert bool((src.sort(1).values[:, 1:] != src.sort(1).values[:, :-1]).all()), "重なりが残っている"\n    b.cl_src = src.reshape(-1).to(device=b.cl_src.device, dtype=b.cl_src.dtype)\nprint(f"CL {NCL} 体 ／ CL → 皮質 受け手 {nr_}・1体 {K} 本・{\'別々の体から\' if DISTINCT else \'重なりあり（今の引き方）\'}"\n      f" ／ 網の中の辺 {len(g.e_src):,}・下からの線 {len(b.but.w):,}・CL の線 {len(b.cl_w):,}・体 {g.n_ch_all:,}・受け手の行 {g.n_recv_all:,}", flush=True)\nif COUNT:\n    sys.exit(0)\nPPS = slice(int(b.off_ch[NAMES.index("PPN")]), int(b.off_ch[NAMES.index("PPN")]) + b.n["PPN"])\nif PPN_SPREAD:\n    import math\n    o_ = 0\n    for k_ in TB.NUC:\n        if k_ == "PPN":\n            break\n        o_ += b.n[k_]\n    npp = b.n["PPN"]\n    v_ = b.nuc_i0[o_:o_ + npp]\n    assert o_ + npp <= len(b.nuc_i0) and float(v_.max() - v_.min()) <= 1e-6 * float(v_.max()), "PPN の i0 の場所が思っていた形でない"\n    print(f"PPN の i0（ばらす前・ノブ込み）{float(v_[0]):.5f}", flush=True)\n    if PPN_FREE:\n        kn_ = float(TB.KNOBS.get("nuc_vinf", {}).get("PPN", 1.0))\n        KF = kn_                                         # 既定：ノブの倍率はそのまま（容器で切り離した PPN：倍率 1 で 約5.5Hz・1.5 で 約9Hz【測】⇒ 2.81 で 約18Hz の見込み【計算】）\n        for a_ in sys.argv[1:]:\n            if a_.startswith("--ppn-k="):\n                KF = float(a_[8:])\n        b.nuc_i0[o_:o_ + npp] *= KF / kn_                # ノブの倍率を外し、切り離した PPN が約 23Hz になる倍率 KF を掛ける（容器で合わせた値を渡す）\n        nn_ = g.nucnet\n        _s, d_, sg_, _dl = nn_.flat()\n        op_ = int(b.off_ch[NAMES.index("PPN")])\n        msk = (d_ >= op_) & (d_ < op_ + npp)\n        assert int(msk.sum()) > 0 and bool((sg_[msk] < 0).all()), "PPN へ入る線が思っていた形でない（抑制だけのはず）"\n        nn_.w[msk] = 0.0\n        nn_.w0[msk] = 0.0\n        print(f"PPN を入力から切り離した：PPN へ入る抑制の線 {int(msk.sum()):,} 本の重さを 0・i0 のノブの倍率 {kn_:.3f} を外して {KF:.3f} を掛けた", flush=True)\n    if PPN_NOI:\n        ip_ = NAMES.index("PPN")\n        lo_, hi_ = int(g.off_recv[ip_]), int(g.off_recv[ip_ + 1])\n\n        def ppn_noi():                                   # PPN の中の 抑制の体 → 体 の辺の重さを 0（刈り込みのあとにも当て直す：11-17 23:23 の回で 1000歩から率が 25 → 7Hz）\n            n0 = 0\n            for a0 in range(0, len(g.e_recv), 1 << 22):      # 11-18：4M ずつ・32bit のまま比べる（1つの GPU の仕事を短く）\n                r_ = g.e_recv[a0:a0 + (1 << 22)]\n                m_ = g.e_inh[a0:a0 + (1 << 22)] & (r_ >= lo_) & (r_ < hi_)\n                w_ = g.w[a0:a0 + (1 << 22)]\n                n0 += int((m_ & (w_ != 0)).sum())\n                w_[m_] = 0.0\n                L.beat()\n            return n0\n        n0 = ppn_noi()\n        print(f"PPN の中の 抑制の体 → 体（全部の行）の辺 {n0:,} 本の重さを 0（刈り込みの歩のあとにも当て直す）", flush=True)\n    M, SD = 23.2, 15.6                                   # 【ヒト】JNNP 2010（32体）\n    sg2 = math.log(1.0 + (SD / M) ** 2)\n    gp_ = torch.Generator(device="cpu"); gp_.manual_seed(113)\n    hz = torch.exp(math.log(M) - sg2 / 2 + math.sqrt(sg2) * torch.randn(npp, generator=gp_)).clamp(0.5, 90.0)\n    vinf = 1.0 / (1.0 - torch.exp(-(1000.0 / hz) / TB.TAU_M_NUC))\n    ratio = (vinf / TB.NUC_VINF["PPN"]).to(b.nuc_i0.device, b.nuc_i0.dtype)\n    b.nuc_i0[o_:o_ + npp] *= ratio\n    print(f"PPN {npp} 体：i0 を体ごとにばらした（引いた率 平均 {float(hz.mean()):.1f}・SD {float(hz.std()):.1f}・中央 {float(hz.median()):.1f}Hz・"\n          f"i0 の倍率 {float(ratio.min()):.2f}〜{float(ratio.max()):.2f}・中央 {float(ratio.median()):.2f}）", flush=True)\nn_all = g.n_ch_all\nDT = 10.67 / 1000.0\nCX = [n for n in NAMES if TB.PRIOR_TYPE.get(n) == "皮質" and n != "運動"]\nHIP = [n for n in ("歯状回", "CA3", "CA1") if n in NAMES]\nSL = {nm: slice(int(b.off_ch[NAMES.index(nm)]), int(b.off_ch[NAMES.index(nm)]) + b.n[nm]) for nm in CX + ["運動"] + HIP}\n\nALL = CX + ["運動"]\nch0_name = {int(b.off_ch[NAMES.index(nm)]): nm for nm in NAMES}\nis_rep_r = torch.zeros(g.n_recv_all, dtype=torch.bool, device=dev)\nis_rep_r[g.rep_i.long()] = True\nRR = {}\nfor nm in ALL:\n    i = NAMES.index(nm)\n    rr = torch.arange(int(g.off_recv[i]), int(g.off_recv[i + 1]), device=dev)\n    RR[nm] = rr[is_rep_r[rr]]\ntab = b.but\npaths = {nm: [] for nm in ALL}                           # 領野 → [(切り出し, 受け手の数)]\nfor i, k in enumerate(tab.keys):\n    nm = ch0_name.get(int(b.bu[k].ch0), "?")\n    if nm in paths:\n        paths[nm].append((slice(int(tab.eo[i]), int(tab.eo[i + 1])), max(1, tab.nt[i])))\ncl_on = bool(getattr(b, "cl_on", False))\nif cl_on:\n    nr = len(b.cl_ch)\n    kcl = len(b.cl_w) // nr\n    assert kcl * nr == len(b.cl_w) and bool((b.cl_recv.long().view(nr, kcl) == torch.arange(nr, device=dev)[:, None]).all()), "CL の並びが思っていた形でない"\n    cl_ch = b.cl_ch.long()\n    CLM = {nm: (cl_ch >= SL[nm].start) & (cl_ch < SL[nm].stop) for nm in ALL}\n\n\ndef weights():\n    q = g.rate_ema / g.target_recv.clamp(min=1e-9)\n    clw = b.cl_w.view(nr, kcl).sum(1, dtype=torch.float64) if cl_on else None\n    out = {}\n    for nm in ALL:\n        wa = sum(float(tab.w[s].sum(dtype=torch.float64)) / nt for s, nt in paths[nm])\n        cw = float(clw[CLM[nm]].mean()) if cl_on and bool(CLM[nm].any()) else float("nan")\n        out[nm] = (float(q[RR[nm]].median()), wa, cw)\n    return out\n\n\ncx_mask = torch.zeros(n_all, dtype=torch.bool, device=dev)\nfor nm in CX:\n    cx_mask[SL[nm]] = True\nCLS = slice(int(b.off_ch[NAMES.index("CL")]), int(b.off_ch[NAMES.index("CL")]) + NCL)\nfor a_ in sys.argv[1:]:\n    if TEST and a_.startswith("--rw="):                 # 容器の確かめだけ：刈り込みの間隔を縮める\n        g.rewire_every = int(a_[5:])\nnoi_log = []\nnoi_n, noi_s = [0], [0.0]\nNOI_EVERY = 10 if TEST else 100\nrw_last = [g.t // NOI_EVERY]\nquiet, big, tot = 0, 0.0, 0.0\npp_big, pp_tot, cl_big, cl_tot = 0.0, 0.0, 0.0, 0.0\nst0 = dict(life.stats)\nif TABLE:\n    off_ = [int(x) for x in b.off_ch]\n    lo_t = torch.tensor(off_[:-1], device=dev); hi_t = torch.tensor(off_[1:], device=dev)\n    size_t = np.array([off_[i + 1] - off_[i] for i in range(len(NAMES))], dtype=np.float64)\n    RT = torch.zeros(NS, len(NAMES), device=dev)\n    z1 = torch.zeros(1, device=dev)\nacc = torch.zeros(n_all, device=dev)\nprint(f"版 {B.VERSION} ／ {NS} 歩・刻み {EV} 歩（{EV * DT:.1f} 秒）／ 皮質（運動の外）{len(CX)} 領野 ／ 体 {n_all:,}", flush=True)\nprint(f"  {\'歩\':>6s} ｜ 皮質 {\'率Hz\':>6s}{\'q\':>6s}{\'下からw\':>8s}{\'CLw\':>7s} ｜ 運動 {\'率Hz\':>6s}{\'q\':>6s}{\'下からw\':>8s}{\'CLw\':>7s} ｜ {\'CA1\':>5s}{\'CL\':>6s} ｜ 黙った歩・一度に撃つ分 ｜ PPN Hz・一度・CL 一度 ｜ 門 ｜ 声・自発・言えた", flush=True)\nfor i in range(1, NS + 1):\n    life.step(learn=True)\n    if PPN_NOI and g.t // NOI_EVERY != rw_last[0]:         # 100歩ごと（11-18：容器で、戻るのが刈り込みの歩ちょうどではなかった）\n        rw_last[0] = g.t // NOI_EVERY\n        import time as _tm\n        t0_ = _tm.perf_counter()\n        nz_ = ppn_noi()\n        if str(dev).startswith("cuda"):\n            torch.cuda.synchronize()                     # 11-18：当て直しの GPU の仕事を、次の歩の時間（守りの 0.5秒）に入れない\n        L.beat()\n        if nz_:\n            noi_log.append((life.t, nz_, round(_tm.perf_counter() - t0_, 3)))\n        noi_n[0] += 1; noi_s[0] = max(noi_s[0], _tm.perf_counter() - t0_)\n    f = g._any[0][:n_all].float()\n    acc.add_(f)\n    if TABLE:\n        c_ = torch.cat([z1, f.cumsum(0)])\n        RT[i - 1] = c_[hi_t] - c_[lo_t]\n    fr = float(f[cx_mask].mean())                        # この歩に皮質（運動の外）で撃った体の割合\n    quiet += int(fr == 0.0)\n    tot += fr\n    if fr >= 0.2:\n        big += fr\n    fp = float(f[PPS].mean()); fc = float(f[CLS].mean())  # PPN・CL：体の 50% 以上が同じ歩に撃った歩に入る発火の割合を数える\n    pp_tot += fp; cl_tot += fc\n    if fp >= 0.5:\n        pp_big += fp\n    if fc >= 0.5:\n        cl_big += fc\n    if i % EV == 0:\n        L.beat()\n        r = acc / EV / DT\n        W = weights()\n        L.beat()\n        cx = np.array([[float(r[SL[nm]].mean()), *W[nm]] for nm in CX]).mean(0)\n        mo = [float(r[SL["運動"]].mean()), *W["運動"]]\n        th = g.third.reshape(-1).tolist() if torch.is_tensor(g.third) else list(g.third)\n        print(f"  {life.t:6d} ｜      {cx[0]:6.2f}{cx[1]:6.2f}{cx[2]:8.3f}{cx[3]:7.3f} ｜      {mo[0]:6.2f}{mo[1]:6.2f}{mo[2]:8.3f}{mo[3]:7.3f} ｜ "\n              f"{float(r[SL[\'CA1\']].mean()):5.2f}{float(r[CLS].mean()):6.2f} ｜ {quiet / EV:5.0%}・{(big / tot if tot > 0 else 0.0):5.0%} ｜ {float(r[PPS].mean()):5.1f}・{(pp_big / pp_tot if pp_tot > 0 else 0.0):4.0%}・{(cl_big / cl_tot if cl_tot > 0 else 0.0):4.0%} ｜ "\n              f"{\'・\'.join(f\'{x:.2f}\' for x in th)} ｜ {life.stats[\'voices\'] - st0[\'voices\']}・{life.stats[\'spont\'] - st0[\'spont\']}・{life.stats[\'ok\'] - st0[\'ok\']}/{life.stats[\'tried\'] - st0[\'tried\']}", flush=True)\n        acc.zero_(); quiet, big, tot = 0, 0.0, 0.0; pp_big, pp_tot, cl_big, cl_tot = 0.0, 0.0, 0.0, 0.0; st0 = dict(life.stats)\nif str(dev).startswith("cuda"):\n    import vram_peak as VP\n    print(f"  ［VRAM］GPU 全体の山（1秒ごと）{VP.peak():.2f}GB・PyTorch の取り置きの山 {torch.cuda.max_memory_reserved() / 1024 ** 3:.2f}GB", flush=True)\nif PPN_NOI:\n    print(f"0 に当て直した（{noi_n[0]} 回見た・一番長くかかった {noi_s[0]:.3f}秒）：戻っていた辺（歩, 本, 秒）{noi_log}", flush=True)\nif TABLE:\n    L.beat()\n    Xt = RT.cpu().numpy().astype(np.float64) / np.maximum(size_t, 1.0)[None, :]\n    np.savez_compressed("cl112_table.npz", rate=Xt.astype(np.float32), names=np.array(NAMES), dt=DT, version=B.VERSION)\n    print("cl112_table.npz に 歩 × 領野 の表を書いた", flush=True)\nprint("\\n（終わり）", flush=True)\n'), 'measure_wave111c.py': ('339b59cc4628dd460f5eaea872ab552abae9394640b8bff441cafb099e699f7b', '"""版110・111：揺れを「波」として見る —— 全部の領野・核の表現の発火を1歩ごとに取り、速い揺れ・領野どうしの先後を出す（arkhe の ~/anaplex で。網は変えない）\n  python3 measure_wave111c.py [歩=15000] [CLの体数]\n    CLの体数を書くと、版111 の上で CL の体数と CL → 皮質 の線（受け手1体の 40本を別々の体から）だけ差し替える（measure_cl112 と同じ差し替え）。表は wave111c_cl体数.npz\n  何のため：【み】11-16 22:37「波が出ているのかも見逃さないようにしてね」（10 §1：波・渦は外せない／波は伝達とシナプスの経路の変化が立ち上げるもの）\n    wave111・111b は刻み 200歩（2.1秒）の平均なので、見えたのは約40秒の揺れだけ。その中の速い揺れ（歩の刻み 10.67ms ⇒ 約47Hz まで）と、\n    領野から領野へ伝わる先後（領野どうしは1歩に1回伝わる、10 §4）は見えていない ⇒ 揺れを直す前に、波かどうか・何を崩すかを見る\n  取るもの：毎歩、領野・核ごとの「撃った体の割合」（歩 × 領野の表）⇒ 終わりに wave111c.npz に書く（測りの表だけ。網は保存しない）\n  出すもの（終わりに1回。始めの 3000歩は捨てる）\n    ① 皮質（運動の外）の平均の揺れの帯ごとの強さ（全体に対する割合）と、帯の中で一番強い周期\n    ② 遅い揺れの先後：100歩でならした率を皮質の平均と比べ、一番合うずれ（歩。負＝皮質の平均より先）と合い方。領野・核ごと\n    ③ 速い先後：1歩ごとの率（100歩のならしを引いたもの）を皮質の平均と比べ、ずれ −3〜＋3歩の合い方。領野・核ごと\n    ④ 立ち上がりの順：皮質の平均が谷から山へ上がるたび、各領野が「自分の山の半分」を越えた歩（皮質の平均が越えた歩との差）\n  毎歩に足す仕事：表現の発火（体の数 110,406）の累積和 1回・領野の端の読み（領野の数）・表の1行への書き込み。\n    線・辺には触らない・少ない箱への足し込み（index_add・scatter）なし・網と同じ大きさの写しは累積和の1本だけ（体の数）\n  歩は life.step（見張り・休み・止めはそのまま働く）。グラフで回す（ふだんと同じ）。終わりの計算は CPU（numpy）で、区切りごとに beat\n  ⚠️ 位置（空間の並び）は領野の中に無いので、見えるのは領野・核どうしの先後だけ（領野の中を進む波・渦はこの道具では見えない）\n"""\nimport sys, numpy as np, torch\nimport babble as B, brainstem as BS, torch_area as T\nimport torch_brain as TB, life as L\nfrom torch_brain import Brain, NAMES\n\nargs = [a for a in sys.argv[1:] if not a.startswith("--")]\nNS = int(args[0]) if args else 15000\nNCL = int(args[1]) if len(args) > 1 else None\nOUT = f"wave111c_cl{NCL}.npz" if NCL else "wave111c.npz"\nTEST = "--test" in sys.argv\nif TEST:\n    B.DEV = "cpu"\ndev = B.DEV\nif B.VERSION not in (110, 111, 112, 113):\n    raise SystemExit(f"⚠️ 版 {B.VERSION}：この道具は版110・111 で回す")\n\nif NCL:\n    assert B.VERSION == 111 and TB.N_CL == 5 and TB.N_NEW["CL"] == 5, "CL の差し替えは版111（N_CL 5）の上で"\n    TB.N_CL = NCL\n    TB.N_NEW["CL"] = NCL\ntorch.manual_seed(0)\nb = Brain(T.Prior.load("prior_v1.npz", dev=dev), n_partner=(200 if TEST else 9100), hippo_scale=20.0, n_ear=B.N_EAR, dev=dev)\nb.bs.set_state(BS.WAKE)\nlife = B.life_of(b, True, np.random.default_rng(0), np.random.default_rng(1))\ng = b.g\nif NCL:\n    nr_ = len(b.cl_ch)\n    K = len(b.cl_w) // nr_\n    assert b.n["CL"] == NCL and NCL >= K\n    gc_ = torch.Generator(device="cpu"); gc_.manual_seed(112)\n    src = torch.empty(nr_, K, dtype=torch.long)\n    for a0 in range(0, nr_, 512):\n        src[a0:a0 + 512] = torch.rand(min(512, nr_ - a0), NCL, generator=gc_).argsort(1)[:, :K]\n    b.cl_src = src.reshape(-1).to(device=b.cl_src.device, dtype=b.cl_src.dtype)\n    print(f"CL {NCL} 体・CL → 皮質 は受け手1体 {K} 本を別々の体から", flush=True)\nn_all = g.n_ch_all\nDT = 10.67 / 1000.0\noff = [int(x) for x in b.off_ch]\nassert off[-1] <= n_all, "領野の端が体の数を越えている"\nlo = torch.tensor(off[:-1], device=dev)\nhi = torch.tensor(off[1:], device=dev)\nsize = np.array([off[i + 1] - off[i] for i in range(len(NAMES))], dtype=np.float64)\nCXI = [i for i, n in enumerate(NAMES) if TB.PRIOR_TYPE.get(n) == "皮質" and n != "運動"]\nR = torch.zeros(NS, len(NAMES), device=dev)\nzero = torch.zeros(1, device=dev)\n\nprint(f"版 {B.VERSION} ／ {NS} 歩 ／ 領野・核 {len(NAMES)}・皮質（運動の外）{len(CXI)} ／ 体 {n_all:,}", flush=True)\nfor i in range(NS):\n    life.step(learn=True)\n    c = torch.cat([zero, g._any[0][:n_all].float().cumsum(0)])\n    R[i] = c[hi] - c[lo]\n    if (i + 1) % 1000 == 0:\n        print(f"  {i + 1} 歩", flush=True)\nL.beat()\nX = R.cpu().numpy().astype(np.float64) / np.maximum(size, 1.0)[None, :]     # 歩 × 領野：撃った体の割合\nnp.savez_compressed(OUT, rate=X.astype(np.float32), names=np.array(NAMES), dt=DT, version=B.VERSION)\nL.beat()\n\nSKIP = min(3000, NS // 5)\nX = X[SKIP:]\nn = len(X)\nhz = X / DT\ncx = hz[:, CXI].mean(1)\nprint(f"\\n（始めの {SKIP} 歩を捨てた。残り {n} 歩 ＝ {n * DT:.0f} 秒）皮質の平均 {cx.mean():.2f}Hz・1発も撃たない歩 {float((X[:, CXI].sum(1) == 0).mean()):.0%}", flush=True)\n\n# ① 帯ごとの強さ\nx0 = cx - cx.mean()\nP = np.abs(np.fft.rfft(x0 * np.hanning(n))) ** 2\nF = np.fft.rfftfreq(n, DT)\ntot = P[1:].sum()\nprint("\\n① 皮質の平均の揺れ：帯ごとの強さ（全体に対する割合）と帯の中で一番強い周期", flush=True)\nfor a_, b_, nm in ((0, 0.1, "0.1Hz より遅い"), (0.1, 1, "0.1〜1Hz"), (1, 4, "1〜4Hz（δ）"), (4, 8, "4〜8Hz（θ）"), (8, 13, "8〜13Hz（α）"),\n                   (13, 30, "13〜30Hz（β）"), (30, 47, "30〜47Hz（γ の下）")):\n    m = (F > a_) & (F <= b_) if a_ > 0 else (F > 0) & (F <= b_)\n    if not m.any():\n        continue\n    k = np.argmax(np.where(m, P, -1))\n    print(f"  {nm:<16s}{P[m].sum() / tot:7.1%}   一番強い {F[k]:7.3f}Hz（周期 {1 / F[k]:7.2f} 秒）", flush=True)\nL.beat()\n\n\ndef smooth(v, w=100):\n    w = max(1, min(w, n // 4))\n    k = np.ones(w) / w\n    return np.convolve(v, k, mode="same")\n\n\ndef corr(a, b_, lag):\n    """a（領野）を lag 歩 遅らせて b_（皮質の平均）と合わせる ⇒ 正の lag で合う ＝ 領野が皮質の平均より遅れている"""\n    if lag > 0:\n        u, v = a[lag:], b_[:-lag]\n    elif lag < 0:\n        u, v = a[:lag], b_[-lag:]\n    else:\n        u, v = a, b_\n    su, sv = u.std(), v.std()\n    return float(((u - u.mean()) * (v - v.mean())).mean() / (su * sv)) if su > 0 and sv > 0 else float("nan")\n\n\ncs = smooth(cx)\nLAGS = [k for k in range(-600, 601, 20) if abs(k) < n // 4]\nprint("\\n② 遅い揺れの先後（100歩のならし。ずれ：負＝皮質の平均より先・正＝あと。1歩 10.67ms）／ ③ 速い先後（ならしを引いた1歩ごと。ずれ −3〜＋3歩の合い方）", flush=True)\nprint(f"  {\'領野\':<8s}{\'平均Hz\':>7s} ｜ {\'ずれ(歩)\':>7s}{\'合い方\':>7s} ｜ " + "".join(f"{k:+6d}" for k in range(-3, 4)), flush=True)\nrows = []\nfor j, nm in enumerate(NAMES):\n    v = hz[:, j]\n    if v.std() == 0:\n        rows.append((9999, f"  {nm:<8s}{v.mean():7.2f} ｜ （撃たない）"))\n        continue\n    vs = smooth(v)\n    cc = [corr(vs, cs, k) for k in LAGS]\n    kb = int(np.nanargmax(cc)) if not np.all(np.isnan(cc)) else 0\n    fast = [corr(v - vs, cx - cs, k) for k in range(-3, 4)]\n    rows.append((LAGS[kb], f"  {nm:<8s}{v.mean():7.2f} ｜ {LAGS[kb]:+7d}{cc[kb]:7.2f} ｜ " + "".join(f"{x:6.2f}" for x in fast)))\n    if j % 10 == 0:\n        L.beat()\nfor _, s in sorted(rows, key=lambda r: r[0]):\n    print(s, flush=True)\nL.beat()\n\n# ④ 立ち上がりの順\nhalf = (cs.max() + cs.min()) / 2\nup = [t for t in range(1, n) if cs[t - 1] < half <= cs[t]]\nups = [t for k, t in enumerate(up) if k == 0 or t - up[k - 1] > min(1000, n // 4)]\nprint(f"\\n④ 立ち上がりの順：皮質の平均（100歩のならし）が {half:.2f}Hz を下から越えた歩（捨てたあとの番号）{ups}", flush=True)\nif ups:\n    d = {}\n    for j, nm in enumerate(NAMES):\n        vs = smooth(hz[:, j])\n        h = (vs.max() + vs.min()) / 2\n        if vs.max() - vs.min() <= 0:\n            continue\n        out = []\n        for t in ups:\n            a0, a1 = max(1, t - 800), min(n, t + 800)\n            seg = [u for u in range(a0, a1) if vs[u - 1] < h <= vs[u]]\n            out.append(min(seg, key=lambda u: abs(u - t)) - t if seg else None)\n        d[nm] = out\n    order = sorted(d, key=lambda k: np.mean([x for x in d[k] if x is not None]) if any(x is not None for x in d[k]) else 9999)\n    print("  （皮質の平均との差。負＝先に上がる。— は前後 800歩に越えた歩なし）", flush=True)\n    for nm in order:\n        print(f"  {nm:<8s}" + "".join(f"{\'—\':>7s}" if x is None else f"{x:+7d}" for x in d[nm]), flush=True)\nif str(dev).startswith("cuda"):\n    import vram_peak as VP\n    print(f"\\n  ［VRAM］GPU 全体の山（1秒ごと）{VP.peak():.2f}GB・PyTorch の取り置きの山 {torch.cuda.max_memory_reserved() / 1024 ** 3:.2f}GB", flush=True)\nprint(f"\\n（終わり）{OUT} に 歩 × 領野 の表を書いた", flush=True)\n'), 'measure_talk110.py': ('1ad1d4928b3d3c8d5e802a87169869f5120c1f24cb9ef5ba0b70abcb0ab66c45', '"""版110：暮らしの歩を「声・準備・返し手・間」に分けて、運動（と運動の発火が届く受け手）の率を測る（arkhe の ~/anaplex で。保存しない・網は変えない）\n  python3 measure_talk110.py [番の並び=10,100]\n  何のため：恒常性の目標を話している・いないで分ける（10 §6【み】11-14）。人の値（Kennedy 2011：分の区間まるごと・声の出ない1人、\n    作業 9.6・音楽 5.7Hz）と並べる前に、網の暮らしで各状態の歩の割合と率を知る（組み表_版111_案 §3b）\n  歩の分け（その歩に使われた番と鳴っていた音から。上が先）【C】\n    声        自分の声が鳴っている歩（口が読んでから声の終わりまで。後ろの静けさ 20歩は入れない）\n    準備・指令  言う番で、語の指令（補助輪）が入っていて声はまだの歩\n    準備・合図  言う番で、合図だけ（指令の前）の歩\n    返し手     返し手の声が鳴っている歩（自分の声と重ならない歩）\n    録音       録音の番\n    間        それ以外（黙る番・声のあとの静けさ・番の終わり待ち）\n  出すもの（区切りごと。区切りの頭で数えを 0 に戻す）\n    状態ごとの歩の数と割合 ／ 運動の表現の率：体の平均・体の中央・1Hz 未満の体の割合 ／ 指令の体・それ以外の体の平均（言う番だけ）\n    運動の発火が届く受け手（聴覚・高次・補足・前補足・44・縁上回）の表現の率（体の平均）／ 全部の歩の平均（分の区間まるごとの見方）\n    番・声・自発・言えた の数\n  毎歩に足す仕事：状態の番号を決める（Python の数個の比べ）・表現の発火（体の数 110,406）を状態の行へ足す 1回・\n    指令の体の発火の和 2回（840体）。線・辺には触らない・少ない箱への足し込みなし・網と同じ大きさの写しなし（term109 の数えと同じ重さ）\n  歩は life.step（見張り・休み・止めはそのまま働く）。グラフで回す（ふだんと同じ）\n"""\nimport sys, numpy as np, torch\nimport babble as B, brainstem as BS, torch_area as T\nimport torch_brain as TB, life as L, config as C\nfrom torch_brain import Brain, NAMES\n\nargs = [a for a in sys.argv[1:] if not a.startswith("--")]\nWIN = [int(x) for x in (args[0] if args else "10,100").split(",")]\nTEST = "--test" in sys.argv\nif TEST:\n    B.DEV = "cpu"\ndev = B.DEV\nif B.VERSION not in (110, 111, 112, 113):\n    raise SystemExit(f"⚠️ 版 {B.VERSION}：この道具は版110 で確かめた（版110 で回す）")\n\nST = ("声", "準備・指令", "準備・合図", "返し手", "録音", "間")\ntorch.manual_seed(0)\nb = Brain(T.Prior.load("prior_v1.npz", dev=dev), n_partner=(200 if TEST else 9100), hippo_scale=20.0, n_ear=B.N_EAR, dev=dev)\nb.bs.set_state(BS.WAKE)\nlife = B.life_of(b, True, np.random.default_rng(0), np.random.default_rng(1))\ng = b.g\nn_all = g.n_ch_all\nDT = 10.67 / 1000.0\nAREAS = [nm for nm in ("運動", "聴覚", "高次", "補足", "前補足", "44", "縁上回") if nm in NAMES]\nSL = {nm: slice(int(b.off_ch[NAMES.index(nm)]), int(b.off_ch[NAMES.index(nm)]) + b.n[nm]) for nm in AREAS}\nMS = SL["運動"]\n\nacc = torch.zeros(len(ST), n_all, device=dev)           # 状態 × 体：表現の発火の数\nn_st = [0] * len(ST)\ncmd_f = torch.zeros(2, device=dev)                       # 言う番で指令の入っている歩：指令の体の発火の和・それ以外の体の発火の和\ncmd_n = [0.0, 0.0]                                       # その体の数 × 歩\nkinds_now = []\n_at0 = life.mix.at\n\n\ndef _at(t):\n    mel, kinds = _at0(t)\n    kinds_now[:] = kinds\n    return mel, kinds\n\n\nlife.mix.at = _at\n\n\ndef one_step():\n    """1歩進めてから、その歩の状態を決める（番の替わり・鳴っていた音は歩の中で決まるので、進めたあとに読む）"""\n    t = life.t\n    se = life.speak_end                                  # 進める前の声の終わり（この歩に口が読んだ声は次の歩から鳴る）\n    v0 = life.stats["voices"]\n    life.step(learn=True)\n    tu = life.turn                                       # この歩に使われた番\n    spoke = life.stats["voices"] > v0                    # この歩に口が読んだ ⇒ この歩のあいだは声はまだ\n    one = None\n    if t < se:\n        s = 0\n    elif tu["kind"] == "言う" and (tu["said"] is None or spoke):\n        s = 1 if (t - tu["t0"]) >= C.GO_LEAD - C.CMD_LEAD else 2\n    elif "返し手" in kinds_now:\n        s = 3\n    elif tu["kind"] == "録音" or "録音" in kinds_now:\n        s = 4\n    else:\n        s = 5\n    if tu["kind"] == "言う" and s in (0, 1):\n        one = tu["one"]\n    f = g._any[0][:n_all].float()\n    acc[s].add_(f)\n    n_st[s] += 1\n    if one is not None:\n        m = f[MS]\n        on = one > 0\n        cmd_f[0] += (m * on).sum()\n        cmd_f[1] += (m * ~on).sum()\n        k = float(on.sum())\n        cmd_n[0] += k\n        cmd_n[1] += b.n["運動"] - k\n\n\ndef report(label, st0):\n    L.beat()\n    tot = max(1, sum(n_st))\n    d = {k: life.stats[k] - st0[k] for k in life.stats}\n    print(f"\\n━━ {label}（{tot} 歩 ＝ {tot * DT:.0f} 秒）番 {d[\'turns\']}・言う番 {d[\'plans\']}・声 {d[\'voices\']}・自発 {d[\'spont\']}"\n          f"・言えた {d[\'ok\']}/{d[\'tried\']}・返し手 {d[\'replies\']} ━━", flush=True)\n    print(f"  {\'状態\':<10s}{\'歩\':>8s}{\'割合\':>7s} ｜ 運動 {\'平均Hz\':>7s}{\'中央Hz\':>7s}{\'1Hz未満\':>8s} ｜ " + "".join(f"{nm:>7s}" for nm in AREAS[1:]), flush=True)\n    rows = [(ST[i], acc[i], n_st[i]) for i in range(len(ST))] + [("全部の歩", acc.sum(0), tot)]\n    for nm_, a, n in rows:\n        if n == 0:\n            print(f"  {nm_:<10s}{0:8d}{0:7.1%}", flush=True)\n            continue\n        r = a / n / DT                                    # 体ごとの率 Hz\n        m = r[MS]\n        print(f"  {nm_:<10s}{n:8d}{n / tot:7.1%} ｜      {float(m.mean()):7.2f}{float(m.median()):7.2f}{float((m < 1).float().mean()):8.0%} ｜ "\n              + "".join(f"{float(r[SL[x]].mean()):7.2f}" for x in AREAS[1:]), flush=True)\n    if str(dev).startswith("cuda"):                      # 11-14：区切りごとに山を出す（守りが止めても、そこまでの山が出力に残る）\n        import vram_peak as VP\n        print(f"  ［VRAM］ここまでの GPU 全体の山（1秒ごと）{VP.peak():.2f}GB・PyTorch の取り置きの山 {torch.cuda.max_memory_reserved() / 1024 ** 3:.2f}GB"\n              f"・PyTorch の外（画面・ほかのプログラム）の一番大きい値 {VP._state.get(\'outside\', 0.0):.2f}GB", flush=True)\n    if cmd_n[0] > 0:\n        print(f"  言う番で指令の入っている歩（声 ＋ 準備・指令）：指令の体 {float(cmd_f[0]) / cmd_n[0] / DT:.2f}Hz"\n              f"（1歩あたり {cmd_n[0] / max(1, n_st[0] + n_st[1]):.0f} 体）・それ以外の体 {float(cmd_f[1]) / max(cmd_n[1], 1) / DT:.2f}Hz", flush=True)\n    L.beat()\n\n\nprint(f"版 {B.VERSION} ／ 番 {WIN} ／ 体 {n_all:,}・運動 {b.n[\'運動\']} ／ 受け手 {AREAS[1:]}", flush=True)\ndone = 0\nfor k in WIN:\n    acc.zero_(); cmd_f.zero_(); cmd_n[:] = [0.0, 0.0]; n_st[:] = [0] * len(ST)\n    st0 = dict(life.stats)\n    goal = life.stats["turns"] + (k - done)\n    while True:                                          # life.run_plans と同じ止め方\n        one_step()\n        if life.stats["turns"] >= goal and life.turn is not None and life._turn_done(life.t) and not life.queue:\n            break\n    report(f"{done}〜{k}番", st0)\n    done = k\nprint("\\n（終わり）", flush=True)\n')}

MSG = "✅ 版114b を外した"

import ast, hashlib, pathlib, sys

bad = []
for f, (h, text) in FILES.items():
    ast.parse(text)
    p = pathlib.Path(f)
    if p.exists() and p.read_text() == text:
        continue
    if h is None:                      # 新しく置くファイル（あれば止まる）
        if p.exists():
            bad.append(f)
        continue
    if not p.exists() or hashlib.sha256(p.read_bytes()).hexdigest() != h:
        bad.append(f)
if bad:
    sys.exit(f"⚠️ {bad} が思っていた形ではない（手で直した所があるか、版が違う）。何も書き換えていない")
for f, (_, text) in FILES.items():
    pathlib.Path(f).write_text(text)
print(MSG)
